-- A rule condition may contain subqueries that read other tables and the
-- event's OLD and NEW rows; they are analysed when the rule is created. An
-- ON SELECT rule is checked as PostgreSQL's DefineQueryRewrite does, and
-- CREATE OR REPLACE RULE "_RETURN" replaces a view's query.
CREATE TABLE t301 (a int, b text);
CREATE TABLE log301 (a int, b text);
CREATE TABLE allowed301 (a int);
INSERT INTO allowed301 VALUES (1), (3);
CREATE RULE ins301 AS ON INSERT TO t301
  WHERE EXISTS (SELECT 1 FROM allowed301 WHERE allowed301.a = new.a)
  DO ALSO INSERT INTO log301 VALUES (new.a, new.b);
CREATE RULE upd301 AS ON UPDATE TO t301 WHERE new.a IN (SELECT a FROM allowed301)
  DO INSTEAD INSERT INTO log301 VALUES (new.a, 'upd');
CREATE RULE del301 AS ON DELETE TO t301 WHERE (SELECT count(*) FROM allowed301) > old.a
  DO INSTEAD NOTHING;
INSERT INTO t301 VALUES (1, 'x'), (2, 'y'), (3, 'z');
SELECT * FROM t301 ORDER BY a;
SELECT * FROM log301 ORDER BY a;
UPDATE t301 SET a = a + 2;
SELECT * FROM t301 ORDER BY a;
SELECT * FROM log301 ORDER BY a, b;
DELETE FROM t301;
SELECT * FROM t301 ORDER BY a;
DROP TABLE allowed301;
DROP TABLE allowed301 CASCADE;
INSERT INTO t301 VALUES (5, 'w');
SELECT * FROM t301 ORDER BY a;
CREATE RULE bad301 AS ON INSERT TO t301 WHERE EXISTS (SELECT 1 FROM nosuch301) DO ALSO SELECT 1;
CREATE RULE bad301 AS ON INSERT TO t301 WHERE (SELECT new.zz) > 0 DO ALSO SELECT 1;
CREATE RULE bad301 AS ON INSERT TO t301 WHERE (SELECT 1, 2) > 0 DO ALSO SELECT 1;
CREATE RULE bad301 AS ON INSERT TO t301 WHERE (SELECT a FROM log301) DO ALSO SELECT 1;
CREATE RULE bad301 AS ON INSERT TO t301 WHERE nosuch DO ALSO NOTIFY n301;
CREATE RULE bad301 AS ON INSERT TO t301 WHERE true DO ALSO (SELECT nosuch; NOTIFY n301);
CREATE RULE bad301 AS ON INSERT TO t301 WHERE true DO ALSO (NOTIFY n301; SELECT nosuch);
CREATE RULE bad301 AS ON INSERT TO t301 WHERE nosuch DO INSTEAD INSERT INTO t301 VALUES (1) RETURNING *;
CREATE RULE bad301 AS ON INSERT TO t301 DO INSTEAD
  (INSERT INTO t301 VALUES (1) RETURNING *; INSERT INTO t301 VALUES (2) RETURNING nosuch);
CREATE RULE "_RETURN" AS ON INSERT TO t301 DO INSTEAD NOTHING;
CREATE RULE r301 AS ON INSERT TO t301 DO INSTEAD NOTHING;
CREATE RULE r301 AS ON INSERT TO t301 DO INSTEAD NOTHING;
CREATE RULE r302 AS ON INSERT TO t301 DO INSTEAD NOTHING;
ALTER RULE r302 ON t301 RENAME TO r301;
-- ON SELECT rules.
CREATE VIEW v301 AS SELECT 1 AS a;
CREATE MATERIALIZED VIEW mv301 AS SELECT 1 AS a;
CREATE RULE s301 AS ON SELECT TO t301 DO INSTEAD SELECT 1;
CREATE RULE s301 AS ON SELECT TO v301 DO INSTEAD SELECT 2;
CREATE RULE s301 AS ON SELECT TO v301 DO ALSO SELECT 2 AS a;
CREATE RULE s301 AS ON SELECT TO v301 DO INSTEAD (SELECT 1 AS a; SELECT 2 AS a);
CREATE RULE s301 AS ON SELECT TO v301 DO INSTEAD INSERT INTO t301 VALUES (1);
CREATE RULE s301 AS ON SELECT TO v301 DO INSTEAD NOTHING;
CREATE RULE s301 AS ON SELECT TO v301 WHERE true DO INSTEAD SELECT 2 AS a;
CREATE RULE s301 AS ON SELECT TO v301 DO INSTEAD
  WITH w AS (INSERT INTO t301 VALUES (1) RETURNING a) SELECT a FROM w;
CREATE RULE s301 AS ON SELECT TO v301 DO INSTEAD SELECT 2 AS a;
CREATE RULE "_RETURN" AS ON SELECT TO v301 DO INSTEAD SELECT 2 AS a;
CREATE OR REPLACE RULE s301 AS ON SELECT TO v301 DO INSTEAD SELECT 2 AS a;
CREATE OR REPLACE RULE "_RETURN" AS ON SELECT TO v301 DO INSTEAD SELECT 2 AS b;
CREATE OR REPLACE RULE "_RETURN" AS ON SELECT TO v301 DO INSTEAD SELECT 'x'::text AS a;
CREATE OR REPLACE RULE "_RETURN" AS ON SELECT TO v301 DO INSTEAD SELECT 3 AS a, 4 AS b;
CREATE OR REPLACE RULE "_RETURN" AS ON SELECT TO v301 DO INSTEAD SELECT;
CREATE OR REPLACE RULE "_RETURN" AS ON SELECT TO v301 DO INSTEAD SELECT a FROM t301;
SELECT * FROM v301 ORDER BY a;
DROP TABLE t301;
SELECT rulename FROM pg_rewrite WHERE ev_class = 'v301'::regclass;
CREATE RULE m301 AS ON INSERT TO mv301 DO INSTEAD NOTHING;
CREATE TABLE p301 (a int) PARTITION BY RANGE (a);
CREATE RULE s301 AS ON SELECT TO p301 DO INSTEAD SELECT 1 AS a;
